<script setup lang="ts">
import { computed, reactive, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ElMessage, ElMessageBox } from "element-plus";
import { adminDelete, adminGet, adminPost, adminPut } from "../../../admin/api/adminClient";
import { teacherDelete, teacherGet, teacherPost, teacherPut } from "../../../teacher/teacherApi";
import { adminPath } from "../../../utils/adminPath";
import { formatDisplayDateTime } from "../../../lib/format";

type Problem={id:number;title:string;difficulty:number;timeLimit?:number;memoryLimit?:number};type Folder={id:number;name:string;description:string;displayOrder:number;problemCount:number;problems:Problem[];createdAt:string;accessScope:"ALL"|"MAJOR"|"PRIVATE";majorId?:number|null;majorName?:string;canEdit:boolean};type Major={id:number;name:string;code:string};type CandidatePage={list:Problem[];total:number};
const route=useRoute();const router=useRouter();const teacherMode=computed(()=>route.path.startsWith("/teacher/"));const folderId=computed(()=>route.params.folderId?Number(route.params.folderId):null);const isCreate=computed(()=>route.path.endsWith("/new"));const basePath=computed(()=>teacherMode.value?"/teacher":adminPath(""));
function get<T>(url:string){return teacherMode.value?teacherGet<T>(url):adminGet<T>(url);}function post<T>(url:string,body?:unknown){return teacherMode.value?teacherPost<T>(url,body):adminPost<T>(url,body);}function put<T>(url:string,body?:unknown){return teacherMode.value?teacherPut<T>(url,body):adminPut<T>(url,body);}function remove<T>(url:string){return teacherMode.value?teacherDelete<T>(url):adminDelete<T>(url);}
const loading=ref(false);const saving=ref(false);const error=ref("");const folders=ref<Folder[]>([]);const folder=ref<Folder|null>(null);const majors=ref<Major[]>([]);const keyword=ref("");const scopeFilter=ref<""|Folder["accessScope"]>("");const accessScope=ref<"ALL"|"MAJOR"|"PRIVATE">("ALL");const form=reactive({name:"",description:"",majorId:undefined as number|undefined});const selected=ref<Problem[]>([]);const source=ref("FOLDER");const sourceFolderId=ref<number|undefined>();const candidateKeyword=ref("");const candidatePage=ref(1);const candidateTotal=ref(0);const candidates=ref<Problem[]>([]);const candidateLoading=ref(false);const folderPage=ref(1);const folderPageSize=ref(10);const filteredFolders=computed(()=>folders.value.filter(item=>(!keyword.value||item.name.toLowerCase().includes(keyword.value.toLowerCase()))&&(!scopeFilter.value||item.accessScope===scopeFilter.value)));const pagedFolders=computed(()=>filteredFolders.value.slice((folderPage.value-1)*folderPageSize.value,folderPage.value*folderPageSize.value));watch([keyword,scopeFilter],()=>{folderPage.value=1;});watch(filteredFolders,()=>{const lastPage=Math.max(1,Math.ceil(filteredFolders.value.length/folderPageSize.value));if(folderPage.value>lastPage)folderPage.value=lastPage;});const sourceFolders=computed(()=>folders.value.filter(item=>item.id!==folderId.value));
async function loadList(){loading.value=true;error.value="";try{folders.value=await get<Folder[]>("/api/admin/v1/problem-folders");}catch(cause){error.value=cause instanceof Error?cause.message:"文件夹列表加载失败";}finally{loading.value=false;}}
async function loadDetail(){if(!folderId.value)return;loading.value=true;error.value="";try{const [detail,all,majorRows]=await Promise.all([get<Folder>(`/api/admin/v1/problem-folders/${folderId.value}`),get<Folder[]>("/api/admin/v1/problem-folders"),get<Major[]>("/api/admin/v1/majors?activeOnly=true").catch(()=>[])]);folder.value=detail;folders.value=all;majors.value=majorRows;Object.assign(form,{name:detail.name,description:detail.description??"",majorId:detail.majorId??undefined});accessScope.value=detail.accessScope;selected.value=detail.problems??[];void loadCandidates(1);}catch(cause){error.value=cause instanceof Error?cause.message:"文件夹详情加载失败";}finally{loading.value=false;}}
async function create(){if(!form.name.trim()){ElMessage.warning("请输入文件夹名称");return;}if(accessScope.value==="MAJOR"&&!form.majorId){ElMessage.warning("请选择所属专业");return;}saving.value=true;try{const created=await post<Folder>("/api/admin/v1/problem-folders",{name:form.name.trim(),description:form.description.trim(),displayOrder:0,accessScope:accessScope.value,majorId:form.majorId??null});ElMessage.success("文件夹创建成功");await router.push(`${basePath.value}/problem-folders/${created.id}`);}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"创建失败");}finally{saving.value=false;}}
async function saveInfo(){if(!folderId.value||!form.name.trim()){ElMessage.warning("请输入文件夹名称");return;}if(accessScope.value==="MAJOR"&&!form.majorId){ElMessage.warning("请选择所属专业");return;}saving.value=true;try{await put(`/api/admin/v1/problem-folders/${folderId.value}`,{name:form.name.trim(),description:form.description.trim(),displayOrder:folder.value?.displayOrder??0,accessScope:accessScope.value,majorId:accessScope.value==="MAJOR"?form.majorId:null});ElMessage.success("文件夹信息已保存");await loadDetail();}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"信息保存失败");}finally{saving.value=false;}}
async function saveProblems(){if(!folderId.value)return;saving.value=true;try{await put(`/api/admin/v1/problem-folders/${folderId.value}/problems`,{problemIds:selected.value.map(item=>item.id)});ElMessage.success("文件夹题目已保存");await loadDetail();}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"题目保存失败");}finally{saving.value=false;}}
async function loadCandidates(nextPage=1){if(!folderId.value)return;if(source.value==="FOLDER"&&!sourceFolderId.value){candidates.value=[];candidateTotal.value=0;return;}candidateLoading.value=true;try{const p=new URLSearchParams({source:source.value,page:String(nextPage),pageSize:"10"});if(sourceFolderId.value)p.set("sourceFolderId",String(sourceFolderId.value));if(candidateKeyword.value.trim())p.set("keyword",candidateKeyword.value.trim());const result=await get<CandidatePage>(`/api/admin/v1/problem-folders/${folderId.value}/candidates?${p.toString()}`);candidates.value=result.list??[];candidateTotal.value=result.total??0;candidatePage.value=nextPage;}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"可选题目加载失败");}finally{candidateLoading.value=false;}}
function add(item:Problem){if(!selected.value.some(row=>row.id===item.id))selected.value=[...selected.value,item];}function move(index:number,offset:number){const next=index+offset;if(next<0||next>=selected.value.length)return;const rows=[...selected.value];[rows[index],rows[next]]=[rows[next],rows[index]];selected.value=rows;}
async function deleteFolder(item:Folder){try{await ElMessageBox.confirm("删除文件夹不会删除其中的题目。", "删除文件夹",{type:"warning"});await remove(`/api/admin/v1/problem-folders/${item.id}`);ElMessage.success("文件夹已删除");await loadList();}catch(cause){if(cause!=="cancel"&&cause!=="close")ElMessage.error(cause instanceof Error?cause.message:"删除失败");}}
watch(()=>route.fullPath,()=>{if(isCreate.value){Object.assign(form,{name:"",description:"",majorId:undefined});accessScope.value="ALL";void get<Major[]>("/api/admin/v1/majors?activeOnly=true").then(result=>majors.value=result).catch(()=>majors.value=[]);}else if(folderId.value)void loadDetail();else void loadList();},{immediate:true});
watch(()=>[source.value,sourceFolderId.value,candidateKeyword.value] as const,()=>{if(folderId.value)void loadCandidates(1);});
</script>

<template><section class="folder-page page-container"><el-alert v-if="error" type="error" :title="error" :closable="false" show-icon><template #default><el-button link type="primary" @click="folderId?loadDetail():loadList()">重试</el-button></template></el-alert>
  <el-card v-if="!folderId&&!isCreate" shadow="never"><div class="folder-toolbar">
    <el-input v-model="keyword" clearable placeholder="搜索文件夹" class="search"/>
    <el-button type="primary" @click="router.push(`${basePath}/problem-folders/new`)">新增文件夹</el-button>
    <el-select v-model="scopeFilter" clearable placeholder="开放范围" aria-label="筛选开放范围" class="scope-filter">
      <el-option label="所有人" value="ALL"/><el-option label="本专业" value="MAJOR"/><el-option label="私有" value="PRIVATE"/>
    </el-select>
  </div><el-table v-loading="loading" :data="pagedFolders" stripe><el-table-column prop="name" label="文件夹名称" min-width="180"/><el-table-column prop="description" label="描述" min-width="220"><template #default="{row}">{{row.description||'-'}}</template></el-table-column><el-table-column prop="problemCount" label="题目数量" width="100"/><el-table-column label="开放范围" width="140"><template #default="{row}">{{row.accessScope==='ALL'?'所有人':row.accessScope==='MAJOR'?row.majorName||'本专业':'私有'}}</template></el-table-column><el-table-column label="创建时间" min-width="165"><template #default="{row}">{{formatDisplayDateTime(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" :disabled="!row.canEdit" @click="router.push(`${basePath}/problem-folders/${row.id}`)">编辑</el-button><el-button link type="danger" :disabled="!row.canEdit" @click="deleteFolder(row)">删除</el-button></template></el-table-column></el-table><Pagination class="folder-pagination" v-if="filteredFolders.length" v-model:page="folderPage" v-model:limit="folderPageSize" :page-sizes="[10,20,50]" :total="filteredFolders.length"/><el-empty v-if="!loading&&!filteredFolders.length" description="暂无文件夹"/></el-card>
  <template v-else><el-card v-loading="loading" shadow="never"><template #header><div class="management-card-heading"><div class="management-card-actions"><header class="page-heading"><div class="actions"><el-button v-if="folderId||isCreate" @click="router.push(`${basePath}/problem-folders`)">返回列表</el-button><el-button v-if="!folderId&&!isCreate" type="primary" @click="router.push(`${basePath}/problem-folders/new`)">新建文件夹</el-button><el-button v-if="isCreate" type="primary" :loading="saving" @click="create">创建</el-button></div></header></div></div></template><el-form label-position="top" class="folder-form"><el-form-item label="文件夹名称" required><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="文件夹介绍"><el-input v-model="form.description" type="textarea" :rows="3" maxlength="500" show-word-limit/></el-form-item><el-form-item label="教师开放范围"><el-select v-model="accessScope"><el-option label="所有人" value="ALL"/><el-option label="本专业" value="MAJOR"/><el-option label="私有" value="PRIVATE"/></el-select></el-form-item><el-form-item v-if="accessScope==='MAJOR'" label="所属专业" required><el-select v-model="form.majorId"><el-option v-for="item in majors" :key="item.id" :value="item.id" :label="`${item.name}（${item.code}）`"/></el-select></el-form-item><el-button v-if="folderId" type="primary" :loading="saving" @click="saveInfo">保存文件夹信息</el-button></el-form></el-card><el-row v-if="folderId" :gutter="14"><el-col :xs="24" :xl="12"><el-card shadow="never"><template #header><div class="card-header"><strong>已选题目（{{selected.length}}）</strong><el-button type="primary" :loading="saving" @click="saveProblems">保存题目</el-button></div></template><el-table :data="selected" stripe><el-table-column label="顺序" width="80"><template #default="{ $index }">{{$index+1}}</template></el-table-column><el-table-column prop="title" label="题目" min-width="180"/><el-table-column prop="difficulty" label="难度" width="90"/><el-table-column label="调整" width="150"><template #default="{ $index }"><el-button link :disabled="$index===0" @click="move($index,-1)">上移</el-button><el-button link :disabled="$index===selected.length-1" @click="move($index,1)">下移</el-button><el-button link type="danger" @click="selected=selected.filter(item=>item.id!==selected[$index].id)">移除</el-button></template></el-table-column></el-table></el-card></el-col><el-col :xs="24" :xl="12"><el-card shadow="never"><template #header><strong>可选题目</strong></template><div class="candidate-toolbar"><el-select v-model="sourceFolderId" filterable clearable placeholder="先选择来源题目文件夹" aria-label="来源题目文件夹"><el-option v-for="item in sourceFolders" :key="item.id" :value="item.id" :label="item.name"/></el-select><el-input v-model="candidateKeyword" clearable placeholder="搜索题目 ID、名称或标签"/></div><el-table v-loading="candidateLoading" :data="candidates" size="small"><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="title" label="题目" min-width="160"/><el-table-column prop="difficulty" label="难度" width="80"/><el-table-column label="操作" width="85"><template #default="{row}"><el-button link type="primary" :disabled="selected.some(item=>item.id===row.id)" @click="add(row)">添加</el-button></template></el-table-column></el-table><Pagination :page="candidatePage" :limit="10" :total="candidateTotal" @pagination="({ page }) => loadCandidates(page)"/></el-card></el-col></el-row></template>

</section></template>

<style scoped>.folder-page{display:flex;flex-direction:column;gap:16px}.page-heading,.actions,.card-header,.candidate-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px}.page-heading h1{margin:0;font-size:22px}.page-heading p{margin:6px 0 0;color:var(--el-text-color-secondary);font-size:13px}.folder-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:16px}.folder-toolbar .search{width:220px;max-width:100%}.scope-filter{width:160px}.folder-pagination{margin-top:20px}.folder-form{max-width:760px}.folder-form .el-select{width:100%}.candidate-toolbar{justify-content:flex-start;flex-wrap:wrap;margin-bottom:10px}.candidate-toolbar>*{flex:1;min-width:130px}.card-header>strong{font-size:15px}.folder-page :deep(.pagination-container){margin-top:20px}@media(max-width:700px){.page-heading{align-items:flex-start;flex-direction:column}}</style>
